function modelUpgradeNotice(version:unknown){
 if(version==='illustrative-static-2')return 'Saved experiment upgraded to explicit carbide and the continuous per-tooth force model. Untouched DMC2 Mini placeholders were also corrected. Other inputs, stiffness overrides and limits are preserved; estimates were recalculated.';
 if(version==='illustrative-static-3')return 'Saved experiment upgraded to the continuous per-tooth force model. Untouched DMC2 Mini placeholders were also corrected. Other inputs and limits are preserved; estimates were recalculated.';
 if(version==='illustrative-static-4')return 'Untouched DMC2 Mini placeholders were replaced with the manufacturer-based 2.2 kW / 24,000 RPM profile. Custom machine values and all other inputs were preserved; estimates were recalculated.';
 if(version==='illustrative-static-5')return 'Saved experiment gained tool geometry, body material and shank diameter (flat end mill, body matching the cutter material, shank equal to the cutting diameter). Estimates are unchanged until you edit those fields.';
 return '';
}
function load(){try{const text=localStorage.getItem(STORAGE_KEY),raw=text?JSON.parse(text):null,data=text?parseExperiment(text):fresh();if(!text&&typeof navigator!=='undefined'&&/^en-(US|LR|MM)\b/i.test(navigator.language??''))data.units='imperial';return {data,error:'',notice:modelUpgradeNotice(raw?.modelVersion)};}catch(error){return {data:fresh(),notice:'',error:`Saved data could not be restored: ${String(error)}. Automatic save is paused.`};}}
