 const setLibraries=(next:Library[])=>{const removed=dismissedPreloads(libraries,next,PRELOADED_LIBRARIES);if(removed.length)setDismissed(d=>[...new Set([...d,...removed])]);setLibrariesState(next);};
 useEffect(()=>{if(libraryLoad.error)setNotice(libraryLoad.error);},[libraryLoad.error]);
