 const dialogKind=wizardOpen?'wizard':compareOpen?'compare':'settings',modal=wizardOpen||compareOpen||(inspectorOpen&&!docked);
 useEffect(()=>{const d=dialog.current;if(!d)return;if(modal){if(!d.open)d.showModal();}else if(d.open)d.close();},[modal]);
 useEffect(()=>{if(typeof window.matchMedia!=='function')return;const mq=window.matchMedia(DOCK_QUERY),on=()=>setDocked(mq.matches);mq.addEventListener('change',on);return()=>mq.removeEventListener('change',on);},[]);
 useEffect(()=>{const on=()=>setPanelWidth(w=>clampPanelWidth(w,window.innerWidth));window.addEventListener('resize',on);return()=>window.removeEventListener('resize',on);},[]);
 useEffect(()=>{if(!notice)return;const t=setTimeout(()=>setNotice(''),5000);return()=>clearTimeout(t);},[notice]);
 function remember(){history.current=[...history.current.slice(-29),structuredClone(e)];setHistoryCount(history.current.length);}
 function change(mutator:(next:Experiment)=>void,record=true):string|null{const next=structuredClone(e);mutator(next);try{const checked=parseExperiment(JSON.stringify(next));if(record)remember();setE(checked);return null;}catch(error){return error instanceof Error?error.message:String(error);}}
 function action(mutator:(next:Experiment)=>void){const error=change(mutator);if(error)setNotice(error);}
 function config<K extends keyof Configuration>(group:K,key:keyof Configuration[K],value:number|boolean){return change(n=>{if(group==='limits'){editLimit(n,key as keyof Configuration['limits'],value);return;}if(group==='tool'&&key==='diameter'){n.config.tool=withDiameter(n.config.tool,Number(value));return;}(n.config[group] as unknown as Record<string,unknown>)[key as string]=value;});}
 function view(key:keyof View,value:unknown){action(n=>{(n.view as unknown as Record<string,unknown>)[key]=value;});}
 function select(c:Cut){setE(n=>({...n,point:{rpm:c.rpm,feed:c.feed,wocRatio:c.woc/n.config.tool.diameter,docRatio:c.doc/n.config.tool.diameter}}));}
 function begin(){if(!gesture.current){remember();gesture.current=true;setFrozen(scale);}}
